"""Paths and config files. Everything the pipeline reads from disk starts here."""

from __future__ import annotations

import json
import os
from functools import cache
from pathlib import Path

SIM_DIR = Path(__file__).resolve().parents[1]
REPO_ROOT = SIM_DIR.parent
CONFIG_DIR = SIM_DIR / "config"
RUNS_DIR = SIM_DIR / "runs"
INDEX_PATH = REPO_ROOT / "content" / "cup-notes" / "index.json"
SCENARIO_DIR = REPO_ROOT / "public" / "cup-notes" / "scenarios"

DISCLAIMER = (
    "Synthetic and illustrative. Generated by a language model playing invented people. "
    "Not Starbucks data and not a prediction."
)


def _read_json(name: str) -> dict:
    return json.loads((CONFIG_DIR / name).read_text(encoding="utf-8"))


@cache
def model() -> dict:
    return _read_json("model.json")


@cache
def levers() -> dict:
    return _read_json("levers.json")


@cache
def personas() -> dict:
    return _read_json("personas.json")


def seed() -> int:
    return int(model()["seed"])


def lever_option(lever: str, key: str) -> dict:
    return next(o for o in levers()[lever] if o["key"] == key)


def store(key: str) -> dict:
    return next(s for s in personas()["stores"] if s["key"] == key)


def barista(store_key: str, barista_key: str) -> dict:
    return next(b for b in store(store_key)["baristas"] if b["key"] == barista_key)


def customer(key: str) -> dict:
    return next(c for c in personas()["customers"] if c["key"] == key)


@cache
def prompt(stage: str) -> dict[str, str]:
    """{"system": ..., "user": ...} from config/prompts/<version>/<stage>.md."""
    path = CONFIG_DIR / "prompts" / model()["prompt_version"] / f"{stage}.md"
    sections: dict[str, list[str]] = {}
    current = None
    for line in path.read_text(encoding="utf-8").splitlines():
        if line.startswith("## "):
            current = line[3:].strip()
            sections[current] = []
        elif current is not None:
            sections[current].append(line)
    return {name: "\n".join(sections[name]).strip() for name in ("system", "user")}


def load_env() -> None:
    """Put simulation/.env into os.environ. Never prints or writes the values."""
    path = SIM_DIR / ".env"
    if not path.exists():
        return
    for line in path.read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        name, value = line.split("=", 1)
        os.environ.setdefault(name.strip(), value.strip().strip('"').strip("'"))
